cssVarsTemplate:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 135 22% 7%;
    --card: 0 0% 100%;
    --card-foreground: 135 22% 7%;
    --popover: 0 0% 100%;
    --popover-foreground: 135 22% 7%;
    --primary: 135 21% 11%;
    --primary-foreground: 135 75% 91%;
    --secondary: 135 70% 83%;
    --secondary-foreground: 135 21% 11%;
    --muted: 135 70% 83%;
    --muted-foreground: 135 29% 43%;
    --accent: 135 70% 83%;
    --accent-foreground: 135 21% 11%;
    --destructive: 10 85% 58%;
    --destructive-foreground: 135 75% 91%;
    --border: 135 64% 73%;
    --input: 135 64% 73%;
    --ring: 135 22% 7%;
    --radius: 0.5rem;
    --chart-1: 12 76% 61%;
    --chart-2: 173 58% 39%;
    --chart-3: 197 37% 24%;
    --chart-4: 43 74% 66%;
    --chart-5: 27 87% 67%;
  }

  .dark {
    --background: 135 22% 7%;
    --foreground: 135 75% 91%;
    --card: 135 22% 7%;
    --card-foreground: 135 75% 91%;
    --popover: 135 22% 7%;
    --popover-foreground: 135 75% 91%;
    --primary: 135 75% 91%;
    --primary-foreground: 135 21% 11%;
    --secondary: 135 21% 19%;
    --secondary-foreground: 135 75% 91%;
    --muted: 135 21% 19%;
    --muted-foreground: 135 40% 53%;
    --accent: 135 21% 19%;
    --accent-foreground: 135 75% 91%;
    --destructive: 10 63% 29%;
    --destructive-foreground: 135 75% 91%;
    --border: 135 21% 19%;
    --input: 135 21% 19%;
    --ring: 135 54% 63%;
    --chart-1: 220 70% 50%;
    --chart-2: 160 60% 45%;
    --chart-3: 30 80% 55%;
    --chart-4: 280 65% 60%;
    --chart-5: 340 75% 55%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}
